with cleaned as (select id, name, country, city, signup_date, is_active, credit_limit, age, trim(name) as clean_name, initcap(trim(city)) as city_title from customers where name not like '%Olivia%') select s.id, s.city, s.is_active, s.clean_name, s.city_title, latest.subscription_status from cleaned s left join lateral (select c.status as subscription_status from subscriptions c where c.customer_id = s.id order by c.monthly_fee desc, c.id desc limit 1) latest on true;
